def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the repeating color pattern from the unobscured interior.
    cells = [(r, c, grid[r][c])
             for r in range(3, h) for c in range(3, w)
             if grid[r][c] != 0]

    best_p = 5
    best_map = {}
    for p in range(2, 10):
        counts = [{} for _ in range(p)]
        for r, c, value in cells:
            k = (r + c) % p
            counts[k][value] = counts[k].get(value, 0) + 1
        mapping = {k: max(freq, key=freq.get)
                   for k, freq in enumerate(counts) if freq}
        matches = sum(counts[k][value] for k, value in mapping.items())
        accuracy = matches / max(1, len(cells))
        if accuracy >= 0.92:
            best_p, best_map = p, mapping
            break

    if not best_map:
        best_p = max(
            range(2, 10),
            key=lambda p: sum(
                max((sum(1 for r, c, v in cells
                      if (r + c) % p == k and v == color)
                     for color in set(v for rr, cc, v in cells
                                      if (rr + cc) % p == k)),
                    default=0)
                for k in range(p)
            )
        )
        counts = [{} for _ in range(best_p)]
        for r, c, value in cells:
            k = (r + c) % best_p
            counts[k][value] = counts[k].get(value, 0) + 1
        best_map = {k: max(freq, key=freq.get)
                    for k, freq in enumerate(counts) if freq}

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = best_map.get((r + c) % best_p, 0)
    return out
